using System;using System.Collections.Generic;
namespace LoopPedal {
static class CloudyChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static MasterFx Fixture(int mode,float cloudy){return new MasterFx{GrainMode=mode,Grain=1,GrainMix=1,GrainSize=.06f,CloudWindow=.08f,Position=.08f,Spray=.3f,Spread=.75f,CloudFeedback=0,Cloudy=cloudy};}
 public static void Run(List<string> log){for(int mode=1;mode<=2;mode++)foreach(float feedback in new[]{-.92f,.92f}){var f=Fixture(mode,1);f.CloudFeedback=feedback;f.Density=12;double peak=0;for(int i=0;i<384000;i++){float input=i<192000?(float)(.1*Math.Sin(i*.04)+.02):0,l,r;f.Process(input,input,out l,out r);peak=Math.Max(peak,Math.Abs(l+input));Check(!float.IsNaN(l)&&!float.IsInfinity(l)&&!float.IsNaN(r)&&!float.IsInfinity(r)&&peak<2,"Maximum Cloudy feedback stability");}log.Add("PASS maximum CLOUDY, density and signed feedback with biased audio mode="+mode+" feedback="+feedback+" peak="+peak);}for(int mode=1;mode<=2;mode++){var low=Fixture(mode,0);var high=Fixture(mode,1);double reference=0,difference=0,late=0,lateLow=0;for(int i=0;i<288000;i++){float input=i<48000?(float)(.2*Math.Sin(i*.04)*Math.Exp(-(i%6000)/900.0)):0,al,ar,bl,br;low.Process(input,input,out al,out ar);high.Process(input,input,out bl,out br);al+=input;ar+=input;bl+=input;br+=input;Check(!float.IsNaN(bl)&&!float.IsInfinity(bl)&&Math.Abs(bl)<1,"Bounded Cloudy output");if(i<96000){reference+=al*al+ar*ar;difference+=(al-bl)*(al-bl)+(ar-br)*(ar-br);}if(i>=144000){late+=bl*bl+br*br;lateLow+=al*al+ar*ar;}}Check(difference>reference*.25,"Cloudy endpoint contrast");Check(late>.00001&&late>lateLow*100,"Cloudy diffused tail");log.Add("PASS stronger CLOUDY endpoint contrast mode="+mode+" difference/reference="+difference/reference+" late energy="+late);var fx=Fixture(mode,0);float l=0,r=0;for(int i=0;i<144000;i++){float input=(float)(.15*Math.Sin(i*.032));fx.Process(input,input,out l,out r);}fx.Freeze=true;fx.Cloudy=1;float last=l+(float)(.15*Math.Sin(143999*.032));double step=0;for(int i=0;i<96000;i++){fx.Process(0,0,out l,out r);step=Math.Max(step,Math.Abs(l-last));last=l;}Check(step<.04,"Smooth frozen Cloudy sweep");log.Add("PASS live CLOUDY sweep during Freeze mode="+mode+" max step="+step);}}
}
}
